# *****************************************************************************
# Parameters for mofa_plots_report.Rmd
#
# Edit the settings below before rendering mofa_plots_report.Rmd. The report
# sources this file from its own directory, so keep this file in the same folder
# as mofa_plots_report.Rmd.
# *****************************************************************************

# Specify the location of the MOFA results file generated by mofa_analysis.R.
mofa_res_fname <- file.path(
  "D:/R_sessions/PROSPR/MOFA/",
  "2026_Sep_25_15_23_43_visit=24mo_change_scores_views=me+pr+mb",
  "model.hdf5"
)

# Specify the continuous covariates for which correlations with each MOFA factor
# will be computed. Each covariate must correspond to a column in the clinical
# metadata used for the mofa_analysis.R run.
col_names_to_use <- c(
  "CR", "agebl", "female", "bmistrat", "teerq", "tee86", "teeresid",
  "rmrresid", "coretemp", "cortempd", "cortempn", "pctcr", "mclinwt",
  "mbmi", "blclinwt", "deltawtb", "pdeltawt", "MetS_Score", "INF_Score"
)

# Specify the factors to include in the detailed factor-specific plots. These
# plots are intended for closer examination of factors meaningfully associated
# with covariates of interest, as identified by the factor regression analysis.
# Thus, the regression results should guide the selection of factors specified
# here. It is recommended to select no more than 4-5 factors so that the plots
# remain legible.
sel_facs <- c(22, 16, 34, 39, 27)

# Specify the covariate used in the detailed factor-specific plots. This will
# typically be a covariate showing a strong association with the selected
# factors. One approach is to render the report once, inspect the factor versus
# clinical-covariate association plot, select a covariate of interest, and then
# render the report again.
metadata_col <- "deltawtb"

# Specify the factor used for examining feature weights. This will typically be
# a factor of particular interest based on regression results and/or the plot of
# factor associations with clinical covariates.
top_weight_factor <- 22

# Specify the number of feature weights to display for top_weight_factor.
top_weight_nfeatures <- 50

# Specify the MOFA views for which feature weights should be displayed.
top_weight_views <- c("methylation", "metabolomics", "proteomics")

# Specify the factor used to select features for sample clustering heatmaps.
heatmap_factor <- 22

# Specify the number of features used for sample clustering. For each selected
# view, samples are clustered using the measurements of the features with the
# highest absolute weights for heatmap_factor.
heatmap_features <- 50

# Specify the MOFA views for which sample-clustering heatmaps are generated.
heatmap_views <- c("metabolomics", "proteomics", "methylation")

# Specify metadata covariates used to annotate samples in the heatmap.
heatmap_annotation_samples <- c("CR", "deltawtb")

# Specify whether t-SNE and UMAP dimensionality-reduction plots are generated.
run_dimred <- TRUE
